      <form onSubmit={handleSubmit}>
        <CardContent className="space-y-4">
          {error && (
            <Alert
              variant="destructive"
              className="animate-in fade-in-0 slide-in-from-top-1 duration-300"
            >
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}
          <div className="space-y-2">
            <Label htmlFor="name" className="text-sm font-semibold">
              Name
            </Label>
            <Input
              id="name"
              type="text"
              placeholder="John Doe"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="email" className="text-sm font-semibold">
              Email
            </Label>
            <Input
              id="email"
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="password" className="text-sm font-semibold">
              Password
            </Label>
            <Input
              id="password"
              type="password"
              placeholder="At least 8 characters"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="confirmPassword" className="text-sm font-semibold">
              Confirm Password
            </Label>
            <Input
              id="confirmPassword"
              type="password"
              placeholder="Re-enter your password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>
        </CardContent>
        <CardFooter className="flex flex-col gap-4 pt-2">
          <Button type="submit" size="lg" className="w-full" disabled={loading}>
            {loading && <Loader2 className="mr-2 h-5 w-5 animate-spin" />}
            Create account
          </Button>
          {onLoginClick && (
            <>
              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <span className="w-full border-t" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                  <span className="bg-card px-2 text-muted-foreground">or</span>
                </div>
              </div>
              <p className="text-sm text-center text-muted-foreground">
                Already have an account?{" "}
                <button
                  type="button"
                  onClick={onLoginClick}
                  className="font-semibold text-primary hover:underline transition-colors"
                >
                  Sign in
                </button>
              </p>
            </>
          )}
        </CardFooter>
      </form>
    </Card>
  );
}

"use client";

import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { ArrowLeft, CheckCircle, Loader2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthActions } from "@convex-dev/auth/react";
import { useState } from "react";

/**
 * Props for the ForgotPasswordForm component.
 *
 * @property onBackToLoginClick - Callback when user clicks "Back to login"
 * @property onEnterCodeClick - Callback when user clicks "Enter reset code" after success.
 *   Receives the email address to pass along to the update password form.
 */
interface ForgotPasswordFormProps {
  onBackToLoginClick?: () => void;
  onEnterCodeClick?: (email: string) => void;
}

/**
 * ForgotPasswordForm component for requesting password reset.
 *
 * Per Convex Auth docs, submits with flow: "reset" which triggers
 * the ResendOTPPasswordReset provider to send an OTP code via email.
 *
 * After successful submission, displays a success message and provides
 * callbacks for navigation (since this is framework-agnostic).
 */
export function ForgotPasswordForm({
  onBackToLoginClick,
  onEnterCodeClick,
}: ForgotPasswordFormProps) {
  const { signIn } = useAuthActions();
  const [email, setEmail] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      const formData = new FormData();
      formData.set("email", email);
      formData.set("flow", "reset");

      await signIn("password", formData);
      setSuccess(true);
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to send reset code",
      );
    } finally {
      setLoading(false);
    }
  };

  // Success state - show confirmation and navigation options
  if (success) {
    return (
      <Card className="w-full max-w-md shadow-lg">
        <CardHeader>
          <div className="flex items-center justify-center mb-4">
            <CheckCircle className="h-12 w-12 text-green-500" />
          </div>
          <CardTitle className="text-center">Check your email</CardTitle>
          <CardDescription className="text-center">
            We've sent a password reset code to {email}
          </CardDescription>
        </CardHeader>
        <CardContent className="text-center text-sm text-muted-foreground">
          Enter the 8-digit code from your email to reset your password.
        </CardContent>
        <CardFooter className="flex flex-col gap-4">
          {onEnterCodeClick && (
            <Button onClick={() => onEnterCodeClick(email)} className="w-full">
              Enter reset code
            </Button>
          )}
          {onBackToLoginClick && (
            <Button
              variant="outline"
              onClick={onBackToLoginClick}
              className="w-full"
            >
              <ArrowLeft className="mr-2 h-4 w-4" />
              Back to login
            </Button>
          )}
        </CardFooter>
      </Card>
    );
  }

  return (
    <Card className="w-full max-w-md shadow-lg">
      <CardHeader className="space-y-1 pb-4">
        <CardTitle className="text-2xl">Reset your password</CardTitle>
        <CardDescription>
          Enter your email and we'll send you a code to reset your password
        </CardDescription>
      </CardHeader>
      <form onSubmit={handleSubmit}>
        <CardContent className="space-y-4">
          {error && (
            <Alert
              variant="destructive"
              className="animate-in fade-in-0 slide-in-from-top-1 duration-300"
            >
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}
          <div className="space-y-2">
            <Label htmlFor="email" className="text-sm font-semibold">
              Email
            </Label>
            <Input
              id="email"
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>
        </CardContent>
        <CardFooter className="flex flex-col gap-4 pt-2">
          <Button
            type="submit"
            size="lg"
            className="w-full"
            disabled={loading}
          >
            {loading && <Loader2 className="mr-2 h-5 w-5 animate-spin" />}
            Send reset code
          </Button>
          {onBackToLoginClick && (
            <Button
              type="button"
              variant="ghost"
              onClick={onBackToLoginClick}
              className="w-full"
            >
              <ArrowLeft className="mr-2 h-4 w-4" />
              Back to login
            </Button>
          )}
        </CardFooter>
      </form>
    </Card>
  );
}

"use client";

import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuthActions } from "@convex-dev/auth/react";
import { ArrowLeft, Loader2 } from "lucide-react";
import { useState } from "react";

/**
 * Props for the UpdatePasswordForm component.
 *
 * @property email - Pre-filled email address (e.g., passed from forgot password flow)
 * @property onSuccess - Callback when password is successfully updated
 * @property onRequestNewCodeClick - Callback when user clicks "Request new code"
 */
interface UpdatePasswordFormProps {
  email?: string;
  onSuccess?: () => void;
  onRequestNewCodeClick?: () => void;
}

/**
 * UpdatePasswordForm component for completing password reset.
 *
 * Supports two flows:
 * 1. OTP Code: User enters the 8-digit code received via email + new password
 * 2. Email prop: Email is passed as a prop from the forgot password flow
 *
 * Per Convex Auth docs, the form submits:
 * - code: The verification code
 * - email: The user's email address
 * - newPassword: The new password
 * - flow: "reset-verification"
 */
export function UpdatePasswordForm({
  email: emailProp,
  onSuccess,
  onRequestNewCodeClick,
}: UpdatePasswordFormProps) {
  const { signIn } = useAuthActions();

  const [email, setEmail] = useState(emailProp ?? "");
  const [code, setCode] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // Validation
    if (!email) {
      setError("Email is required");
      return;
    }

    if (!code) {
      setError("Verification code is required");
      return;
    }

    if (password !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    if (password.length < 8) {
      setError("Password must be at least 8 characters");
      return;
    }

    setLoading(true);

    try {
      const formData = new FormData();
      formData.set("code", code);
      formData.set("email", email);
      formData.set("newPassword", password);
      formData.set("flow", "reset-verification");

      await signIn("password", formData);
      onSuccess?.();
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to update password",
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className="w-full max-w-md shadow-lg">
      <CardHeader className="space-y-1 pb-4">
        <CardTitle className="text-2xl">Set new password</CardTitle>
        <CardDescription>
          Enter the code from your email and your new password
        </CardDescription>
      </CardHeader>
      <form onSubmit={handleSubmit}>
        <CardContent className="space-y-4">
          {error && (
            <Alert
              variant="destructive"
              className="animate-in fade-in-0 slide-in-from-top-1 duration-300"
            >
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          {/* Only show email input if not provided via prop */}
          {!emailProp && (
            <div className="space-y-2">
              <Label htmlFor="email" className="text-sm font-semibold">
                Email
              </Label>
              <Input
                id="email"
                type="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                disabled={loading}
                className="h-11"
              />
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="code" className="text-sm font-semibold">
              Verification Code
            </Label>
            <Input
              id="code"
              type="text"
              placeholder="Enter 8-digit code"
              value={code}
              onChange={(e) => setCode(e.target.value)}
              required
              disabled={loading}
              maxLength={8}
              pattern="[0-9]{8}"
              className="h-11"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="password" className="text-sm font-semibold">
              New Password
            </Label>
            <Input
              id="password"
              type="password"
              placeholder="At least 8 characters"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="confirmPassword" className="text-sm font-semibold">
              Confirm New Password
            </Label>
            <Input
              id="confirmPassword"
              type="password"
              placeholder="Re-enter your password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
              disabled={loading}
              className="h-11"
            />
          </div>
        </CardContent>
        <CardFooter className="flex flex-col gap-4 pt-2">
          <Button
            type="submit"
            size="lg"
            className="w-full"
            disabled={loading}
          >
            {loading && <Loader2 className="mr-2 h-5 w-5 animate-spin" />}
            Update password
          </Button>
          {onRequestNewCodeClick && (
            <Button
              type="button"
              variant="ghost"
              onClick={onRequestNewCodeClick}
              className="w-full"
            >
              <ArrowLeft className="mr-2 h-4 w-4" />
              Request new code
            </Button>
          )}
        </CardFooter>
      </form>
    </Card>
  );
}

"use client";

import * as React from "react";
import { Button } from "@/components/ui/button";
import { useAuthActions } from "@convex-dev/auth/react";
import { LogOut } from "lucide-react";

/**
 * Props for the LogoutButton component.
 *
 * Extends all standard Button props with additional customization options.
 *
 * @property showIcon - Whether to show the logout icon (default: true)
 * @property onLogout - Optional callback invoked after successful logout
 */
interface LogoutButtonProps extends React.ComponentProps<typeof Button> {
  showIcon?: boolean;
  onLogout?: () => void;
}

/**
 * LogoutButton component for signing out the current user.
 *
 * Uses Convex Auth's signOut action to clear the session.
 * Fully customizable through standard Button props.
 *
 * @example
 * // Basic usage
 * <LogoutButton />
 *
 * @example
 * // Custom styling and callback
 * <LogoutButton
 *   variant="destructive"
 *   showIcon={false}
 *   onLogout={() => navigate("/login")}
 * >
 *   Log out now
 * </LogoutButton>
 */
export function LogoutButton({
  showIcon = true,
  onLogout,
  children,
  ...props
}: LogoutButtonProps) {
  const { signOut } = useAuthActions();

  const handleClick = async () => {
    await signOut();
    onLogout?.();
  };

  return (
    <Button onClick={handleClick} {...props}>
      {showIcon && <LogOut className="mr-2 h-4 w-4" />}
      {children ?? "Sign out"}
    </Button>
  );
}

import { defineSchema, defineTable } from "convex/server";
import { authTables } from "@convex-dev/auth/server";
import { v } from "convex/values";

/**
 * Schema for password-based authentication.
 * Includes the users table and all required auth tables from @convex-dev/auth.
 *
 * Security considerations:
 * - Email is indexed for fast lookups but never exposed in public queries
 * - emailVerificationTime tracks when email was verified
 * - isAnonymous flag supports gradual account upgrades
 */
export default defineSchema({
  // Auth tables from @convex-dev/auth (authAccounts, authSessions, authVerificationCodes, etc.)
  ...authTables,

  // Users table with profile information
  users: defineTable({
    // Profile fields
    name: v.optional(v.string()),
    email: v.optional(v.string()),
    image: v.optional(v.string()),

    // Auth metadata
    emailVerificationTime: v.optional(v.number()),
    isAnonymous: v.optional(v.boolean()),
  })
    .index("by_email", ["email"])
    .index("by_anonymous", ["isAnonymous"]),
});

import { convexAuth } from "@convex-dev/auth/server";
import { Password } from "@convex-dev/auth/providers/Password";
import Resend from "@auth/core/providers/resend";
import GitHub from "@auth/core/providers/github";
import Google from "@auth/core/providers/google";
import { DataModel } from "./_generated/dataModel";

/**
 * Custom Resend provider for email verification OTP.
 *
 * Sends an 8-digit OTP code for email verification during sign-up.
 * Configure AUTH_RESEND_KEY environment variable to enable.
 */
const ResendOTP = Resend({
  id: "resend-otp-verification",
  apiKey: process.env.AUTH_RESEND_KEY,
  async generateVerificationToken() {
    const code = Array.from({ length: 8 }, () =>
      Math.floor(Math.random() * 10),
    ).join("");
    return code;
  },
  async sendVerificationRequest({ identifier: email, provider, token }) {
    const response = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${provider.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        from: process.env.AUTH_EMAIL_FROM ?? "onboarding@resend.dev",
        to: [email],
        subject: "Verify your email",
        text: `Your verification code is: ${token}\n\nThis code expires in 15 minutes.`,
      }),
    });

    if (!response.ok) {
      throw new Error("Could not send verification email");
    }
  },
});

/**
 * Custom Resend provider for password reset OTP.
 *
 * Sends an 8-digit OTP code for password reset.
 * Configure AUTH_RESEND_KEY environment variable to enable.
 */
const ResendOTPPasswordReset = Resend({
  id: "resend-otp-reset",
  apiKey: process.env.AUTH_RESEND_KEY,
  async generateVerificationToken() {
    const code = Array.from({ length: 8 }, () =>
      Math.floor(Math.random() * 10),
    ).join("");
    return code;
  },
  async sendVerificationRequest({ identifier: email, provider, token }) {
    const response = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${provider.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        from: process.env.AUTH_EMAIL_FROM ?? "onboarding@resend.dev",
        to: [email],
        subject: "Reset your password",
        text: `Your password reset code is: ${token}\n\nThis code expires in 15 minutes.`,
      }),
    });

    if (!response.ok) {
      throw new Error("Could not send password reset email");
    }
  },
});

/**
 * Custom Password provider with:
 * - Email verification during sign-up (via ResendOTP)
 * - Password reset flow (via ResendOTPPasswordReset)
 * - Strong password requirements
 */
const CustomPassword = Password<DataModel>({
  // Require email verification during sign-up
  verify: ResendOTP,

  // Enable password reset via email
  reset: ResendOTPPasswordReset,

  // Custom password validation
  validatePasswordRequirements: (password: string) => {
    if (password.length < 8) {
      throw new Error("Password must be at least 8 characters");
    }
    if (!/[a-z]/.test(password)) {
      throw new Error("Password must contain at least one lowercase letter");
    }
    if (!/[A-Z]/.test(password)) {
      throw new Error("Password must contain at least one uppercase letter");
    }
    if (!/[0-9]/.test(password)) {
      throw new Error("Password must contain at least one number");
    }
  },

  // Customize profile to handle additional user fields
  profile(params) {
    return {
      email: params.email as string,
      name: (params.name as string) || undefined,
    };
  },
});

// Build providers list dynamically based on available env vars
const providers: Parameters<typeof convexAuth>[0]["providers"] = [
  CustomPassword,
];

// Only add GitHub if credentials are configured
if (process.env.AUTH_GITHUB_ID && process.env.AUTH_GITHUB_SECRET) {
  providers.push(GitHub);
}

// Only add Google if credentials are configured
if (process.env.AUTH_GOOGLE_ID && process.env.AUTH_GOOGLE_SECRET) {
  providers.push(Google);
}

/**
 * Convex Auth configuration.
 *
 * Features:
 * - Password authentication with email verification
 * - Password reset via OTP codes
 * - Strong password requirements
 * - Optional GitHub OAuth (if AUTH_GITHUB_ID/SECRET configured)
 * - Optional Google OAuth (if AUTH_GOOGLE_ID/SECRET configured)
 *
 * Environment variables:
 * - AUTH_RESEND_KEY: Resend API key for sending emails (required)
 * - AUTH_EMAIL_FROM: Sender email address (optional)
 * - AUTH_GITHUB_ID, AUTH_GITHUB_SECRET: GitHub OAuth (optional)
 * - AUTH_GOOGLE_ID, AUTH_GOOGLE_SECRET: Google OAuth (optional)
 */
export const { auth, signIn, signOut, store, isAuthenticated } = convexAuth({
  providers,
});

import { query, mutation } from "./_generated/server";
import { v } from "convex/values";
import { getAuthUserId } from "@convex-dev/auth/server";
import { ConvexError } from "convex/values";

/**
 * User validator for internal use.
 * Includes all fields - use publicProfileValidator for external queries.
 */
const userValidator = v.object({
  _id: v.id("users"),
  _creationTime: v.number(),
  name: v.optional(v.string()),
  email: v.optional(v.string()),
  image: v.optional(v.string()),
  emailVerificationTime: v.optional(v.number()),
  isAnonymous: v.optional(v.boolean()),
});

/**
 * Public profile validator - excludes sensitive fields like email.
 * Use this when returning user data to other users.
 */
const publicProfileValidator = v.object({
  _id: v.id("users"),
  name: v.optional(v.string()),
  image: v.optional(v.string()),
});

/**
 * Get the current authenticated user's full profile.
 * Returns null if not authenticated.
 *
 * Security: Only returns data for the authenticated user themselves.
 */
export const current = query({
  args: {},
  returns: v.union(userValidator, v.null()),
  handler: async (ctx: any) => {
    const userId = await getAuthUserId(ctx);
    if (!userId) {
      return null;
    }
    return await ctx.db.get(userId);
  },
});

/**
 * Get a user's public profile by ID.
 * Only returns safe, public fields (name, image).
 *
 * Security: Never exposes email or other sensitive data.
 */
export const get = query({
  args: { userId: v.id("users") },
  returns: v.union(publicProfileValidator, v.null()),
  handler: async (ctx: any, args: any) => {
    const user = await ctx.db.get(args.userId);
    if (!user) {
      return null;
    }
    // Only return public fields
    return {
      _id: user._id,
      name: user.name,
      image: user.image,
    };
  },
});

/**
 * Update the current user's profile.
 * Only allows updating safe fields (name, image).
 *
 * Security:
 * - Requires authentication
 * - Only allows updating own profile
 * - Validates input types
 */
export const updateProfile = mutation({
  args: {
    name: v.optional(v.string()),
    image: v.optional(v.string()),
  },
  returns: v.null(),
  handler: async (ctx: any, args: any) => {
    const userId = await getAuthUserId(ctx);
    if (!userId) {
      throw new ConvexError({
        code: "UNAUTHORIZED",
        message: "You must be logged in to update your profile",
      });
    }

    // Build updates object with only provided fields
    const updates: any = {};
    if (args.name !== undefined) {
      // Sanitize name - trim whitespace, limit length
      const sanitizedName = args.name.trim().slice(0, 100);
      if (sanitizedName) {
        updates.name = sanitizedName;
      }
    }
    if (args.image !== undefined) {
      // Validate image URL format
      if (args.image && !isValidUrl(args.image)) {
        throw new ConvexError({
          code: "INVALID_INPUT",
          message: "Invalid image URL",
        });
      }
      updates.image = args.image;
    }

    if (Object.keys(updates).length > 0) {
      await ctx.db.patch(userId, updates);
    }

    return null;
  },
});

/**
 * Helper to validate URL format.
 */
function isValidUrl(string: string): boolean {
  try {
    const url = new URL(string);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

